solution.javascript:
function wordFrequency(text) {
  const counts = {}
  if (text === '') return counts
  const words = text.split(' ')
  for (let i = 0; i < words.length; i++) {
    const word = words[i]
    if (counts.hasOwnProperty(word)) {
      counts[word] = counts[word] + 1
    } else {
      counts[word] = 1
    }
  }
  return counts
}

