solution.javascript:
function countArrived(guests, arrivals) {
  const invited = {}
  for (let i = 0; i < guests.length; i++) {
    invited[guests[i]] = true
  }
  let count = 0
  for (let i = 0; i < arrivals.length; i++) {
    if (invited.hasOwnProperty(arrivals[i])) count++
  }
  return count
}
